//--------------------------------------------------------------------------//

void vrtc_service( void )
{
	rtc_irq_ack() ; //LPC176X:SHOULD at the beginning, otherwise have double vrtc_service
	reg_execute_quick( vrtc_table );
	
	vrtc_sys_tick++;
}

//--------------------------------------------------------------------------//
UInt32 get_vrtc_sys_tick(void)
{
	return vrtc_sys_tick;
}
